        if (source.slice(i, i + 2) === '/*') { var endComment = source.indexOf('*/', i + 2); if (endComment < 0) throw mvuSyntaxError('注释未闭合', i); i = endComment + 2; continue; }
        var start = i, character = source[i], match, token;
