    wiState.currentWorldBookId = newBook.id;
    wiState.viewMode = 'entries';
    wiState.dirty = true;
    updateWIDirtyIndicator();

    if (dom.wiBookName) dom.wiBookName.value = newBook.name;
    if (dom.wiSearch) dom.wiSearch.value = '';

