// ==================== Auto Summarization Threshold Helpers ====================
function isUnderContextPressure(messageCount) {
    var contextMax = state.settings.contextLength || 20;
    return messageCount > contextMax;
}

function getAutoSummaryThreshold(settings) {
    return (settings && settings.summaryThreshold) || 12;
}

function getAutoSummaryTargetKeep(threshold) {
    return Math.max(4, Math.floor(threshold * 0.38));
}

function getAutoSummaryMinBatch(threshold) {
    return Math.max(5, Math.floor(threshold * 0.38));
}

function getMaxSummaryCoveredEnd(summaries) {
    var max = -1;
    if (!summaries || summaries.length === 0) return max;

    summaries.forEach(function(s) {
        if (typeof s.coveredEnd === 'number' && s.coveredEnd > max) {
            max = s.coveredEnd;
        }
    });
    return max;
}

function getActualVisibleCountForSummary() {
    var conv = getActiveConv();
    if (!conv) return 0;

    var regularMsgs = getAutoSummaryRegularMessages(conv);
    var coverageRanges = getPromptSummaryCoverageRanges(conv.summaries || [], regularMsgs.length, regularMsgs);
    return countAutoSummaryUncoveredMessages(getAutoSummaryUncoveredRuns(regularMsgs, coverageRanges));
}
/**
 * 新手导读（文件：54-summarization-auto-selection.js）
 *
 * 负责什么：这是“自动总结流程”中的“总结、自动处理、选择”部分。
 * 在程序中的位置：它判断何时需要总结、选择消息范围，并把结果写入会话。
 * 从哪里开始看：主要从 `getAutoSummaryRegularMessages(conv)`、`getAutoSummaryUncoveredRuns(allRegular, coverageRanges)`、`buildAutoSummarySelection(conv, settings, getFallbackVisibleCount)` 开始阅读。参数名能提示每个函数需要的数据。
 * 代码如何生效：浏览器不会单独加载这个文件。scripts/build-app.js 会按照 manifest.json 的顺序，
 * 把它与其他分片合并成 assets/js/app.js；因此这里定义的函数可以被后面加载的分片调用。
 * 修改时注意：coveredStart 与 coveredEnd 是历史下标，错误更新会造成消息被重复总结或漏发。
 */
// ==================== Auto Summarization Selection Helpers ====================
function getAutoSummaryRegularMessages(conv) {
    return conv && Array.isArray(conv.messages)
        ? conv.messages.filter(function(m) { return m.role !== 'system'; })
        : [];
}

function isAutoSummaryMessageEligible(message) {
    return !!message && message.stage !== 'second' && String(message.content || '').trim();
}

function getAutoSummaryUncoveredRuns(allRegular, coverageRanges) {
    var runs = [];
    var currentRun = [];

    allRegular.forEach(function(message, index) {
        if (isPromptMessageCoveredBySummary(index, coverageRanges)) {
            if (currentRun.length > 0) runs.push(currentRun);
            currentRun = [];
            return;
        }
        if (isAutoSummaryMessageEligible(message)) currentRun.push(index);
    });

    if (currentRun.length > 0) runs.push(currentRun);
    return runs;
}

function countAutoSummaryUncoveredMessages(runs) {
    return runs.reduce(function(total, run) { return total + run.length; }, 0);
}

function shouldAutoSummarizeByBacklog(currentVisibleCount, threshold) {
    return currentVisibleCount >= threshold;
}

function shouldAutoSummarizeByVisibleCount(actualVisibleCount, threshold) {
    return typeof actualVisibleCount === 'number' && actualVisibleCount >= threshold;
}

function buildAutoSummarySelection(conv, settings, getFallbackVisibleCount) {
    var allRegular = getAutoSummaryRegularMessages(conv);
    if (allRegular.length < 6) return null;

    var threshold = getAutoSummaryThreshold(settings);
    var coverageRanges = getPromptSummaryCoverageRanges(conv.summaries || [], allRegular.length, allRegular);
    var uncoveredRuns = getAutoSummaryUncoveredRuns(allRegular, coverageRanges);
    var currentVisibleCount = countAutoSummaryUncoveredMessages(uncoveredRuns);
    var targetKeep = getAutoSummaryTargetKeep(threshold);
    var minSummarizeBatch = getAutoSummaryMinBatch(threshold);

    var shouldSummarize = shouldAutoSummarizeByBacklog(
        currentVisibleCount,
        threshold
    );

    if (!shouldSummarize && typeof getFallbackVisibleCount === 'function') {
        shouldSummarize = shouldAutoSummarizeByVisibleCount(getFallbackVisibleCount(), threshold);
    }

    if (!shouldSummarize) return null;

    var summarizeCount = currentVisibleCount - targetKeep;
    var selectedRun = uncoveredRuns.find(function(run) {
        return Math.min(run.length, summarizeCount) >= minSummarizeBatch;
    });
    if (!selectedRun) return null;

    var selectedIndexes = selectedRun.slice(0, summarizeCount);
    var startIdx = selectedIndexes[0];
    var endIdx = selectedIndexes[selectedIndexes.length - 1];
    var toSummarize = allRegular.slice(startIdx, endIdx + 1).filter(isAutoSummaryMessageEligible);

    return {
        subset: toSummarize,
        startIdx: startIdx,
        endIdx: endIdx,
        threshold: threshold,
        targetKeep: targetKeep,
        minSummarizeBatch: minSummarizeBatch,
        currentVisibleCount: currentVisibleCount
    };
}
/**
 * 新手导读（文件：54-summarization-auto-runtime.js）
 *
 * 负责什么：这是“自动总结流程”中的“总结、自动处理、运行流程”部分。
 * 在程序中的位置：它判断何时需要总结、选择消息范围，并把结果写入会话。
 * 从哪里开始看：主要从 `autoSummarize(conversation)` 开始阅读。参数名能提示每个函数需要的数据。
 * 代码如何生效：浏览器不会单独加载这个文件。scripts/build-app.js 会按照 manifest.json 的顺序，
 * 把它与其他分片合并成 assets/js/app.js；因此这里定义的函数可以被后面加载的分片调用。
 * 修改时注意：coveredStart 与 coveredEnd 是历史下标，错误更新会造成消息被重复总结或漏发。
 */
// ==================== Auto Summarization Runtime ====================
function reportAutoSummaryFailure(error) {
    var detail = error && error.message ? error.message : String(error || '');
    var message = t('summary_auto_failed') + (detail ? ': ' + detail : '');
    console.warn('[Summary] ' + message);
    if (typeof alert === 'function') alert(message);
}

function autoSummarize(conversation) {
    if (!state.settings.summaryEnabled) return;

    var conv = conversation === undefined ? getActiveConv() : conversation;
    if (!isLiveConversation(conv)) return;

    var selection = buildAutoSummarySelection(conv, state.settings,
        conv === getActiveConv() ? getActualVisibleCountForSummary : null);
    if (!selection) return;

    performSummarization(selection.subset, selection.startIdx, selection.endIdx, function(err) {
        if (err) {
            reportAutoSummaryFailure(err);
            return;
        }
        if (isLiveConversation(conv) && conv === getActiveConv()) renderTokenBar();
    }, conv);
}
/**
 * 新手导读（文件：55-summary-history-render.js）
 *
 * 负责什么：这是“总结历史界面”中的“总结、历史记录、渲染”部分。
 * 在程序中的位置：它展示已有总结并提供查看、编辑和删除操作。
 * 从哪里开始看：主要从 `getSummaryHistoryMessageCount(conv)`、`buildSummaryHistoryRangeText(summary, currentMsgCount)`、`buildSummaryHistoryItemHtml(summary, currentMsgCount)`、`bindSummaryHistoryActions(container)` 开始阅读。参数名能提示每个函数需要的数据。
 * 代码如何生效：浏览器不会单独加载这个文件。scripts/build-app.js 会按照 manifest.json 的顺序，
 * 把它与其他分片合并成 assets/js/app.js；因此这里定义的函数可以被后面加载的分片调用。
 * 修改时注意：删除总结会改变后续提示词内容，操作后必须保存并重新渲染。
 */
// 摘要历史渲染辅助：计算消息数量并生成摘要列表项的显示内容。
function getSummaryHistoryMessageCount(conv) {
    return (conv.messages || []).filter(function(m) { return m.role !== 'system'; }).length;
}

function buildSummaryHistoryRangeText(summary, currentMsgCount) {
    if (typeof summary.coveredEnd === 'number' && summary.coveredEnd > currentMsgCount + 50) {
        return '历史摘要（已压缩）';
    }
    return t('summary_covered') + (summary.coveredStart + 1) + t('summary_to') + (summary.coveredEnd + 1) + t('summary_turns_suffix');
}

function buildSummaryHistoryItemHtml(summary, currentMsgCount) {
    summary.validity = getSummaryValidity(summary, getActiveConv());
    var rangeText = buildSummaryHistoryRangeText(summary, currentMsgCount);
    var date = new Date(summary.created).toLocaleString();
    var html = '<div class="glass rounded-xl p-4 group" data-summary-id="' + summary.id + '">';
    html += '<div class="flex items-center justify-between mb-2">';
    html += '<span class="text-[10px] text-zinc-500">' + date + ' &middot; ' + rangeText + '</span>';
    html += '<div class="flex items-center gap-1 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-all">';
    html += '<button class="summary-edit-btn w-5 h-5 rounded-lg flex items-center justify-center text-zinc-500 hover:text-amber-400 hover:bg-amber-500/10 transition-all text-[10px]" data-edit-id="' + summary.id + '" title="' + t('summary_edit') + '">&#9998;</button>';
    html += '<button class="summary-del-btn w-5 h-5 rounded-lg flex items-center justify-center text-zinc-500 hover:text-red-400 hover:bg-red-500/10 transition-all text-xs" data-del-id="' + summary.id + '" title="Delete">&times;</button>';
    html += '</div></div>';
    html += '<div class="mb-2 leading-relaxed">' + renderSummaryValidityLabel(summary) + '</div>';
    html += '<p class="text-xs text-zinc-300 leading-relaxed summary-text" data-text-id="' + summary.id + '">' + escapeHtml(summary.text) + '</p>';
    html += '</div>';
    return html;
}

function bindSummaryHistoryActions(container) {
    container.querySelectorAll('.summary-edit-btn').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();
            var id = btn.getAttribute('data-edit-id');
            editSummary(id);
        });
    });
    container.querySelectorAll('.summary-del-btn').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();
            var id = btn.getAttribute('data-del-id');
            deleteSummary(id);
        });
    });
}
/**
 * 新手导读（文件：55-summary-history-ui.js）
 *
 * 负责什么：这是“总结历史界面”中的“总结、历史记录、界面”部分。
 * 在程序中的位置：它展示已有总结并提供查看、编辑和删除操作。
 * 从哪里开始看：主要从 `renderSummaryHistory(无参数)`、`editSummary(id)`、`deleteSummary(id)` 开始阅读。参数名能提示每个函数需要的数据。
 * 代码如何生效：浏览器不会单独加载这个文件。scripts/build-app.js 会按照 manifest.json 的顺序，
 * 把它与其他分片合并成 assets/js/app.js；因此这里定义的函数可以被后面加载的分片调用。
 * 修改时注意：删除总结会改变后续提示词内容，操作后必须保存并重新渲染。
 */
// 摘要历史界面：展示已有摘要并提供编辑、删除和范围预览入口。
function renderSummaryHistory() {
    var conv = getActiveConv();
    if (!conv || !dom.summaryHistoryList) return;
    var summaries = conv.summaries || [];

    if (summaries.length === 0) {
        dom.summaryHistoryList.innerHTML = '<p class="text-sm text-zinc-500 text-center py-12" data-i18n="summary_no_history">' + t('summary_no_history') + '</p>';
        return;
    }

    var html = '';
    var currentMsgCount = getSummaryHistoryMessageCount(conv);

    for (var i = summaries.length - 1; i >= 0; i--) {
        html += buildSummaryHistoryItemHtml(summaries[i], currentMsgCount);
    }
    dom.summaryHistoryList.innerHTML = html;
    bindSummaryHistoryActions(dom.summaryHistoryList);
}

function editSummary(id) {
    var conv = getActiveConv();
    if (!conv) return;
    var s = conv.summaries.find(function(s) { return s.id === id; });
    if (!s) return;

    // 优先在管理器列表中找，其次在旧历史列表中找
    var textEl = null;
    if (dom.summaryManagerList) textEl = dom.summaryManagerList.querySelector('[data-text-id="' + id + '"]');
    if (!textEl && dom.summaryHistoryList) textEl = dom.summaryHistoryList.querySelector('[data-text-id="' + id + '"]');
    if (!textEl) return;

    var currentText = s.text;
    textEl.innerHTML = '<textarea class="w-full min-h-[80px] px-3 py-2 glass rounded-xl text-xs text-zinc-200 focus:outline-none focus:ring-2 focus:ring-amber-500/30 transition-all resize-none">' + escapeHtml(currentText) + '</textarea>';
    var textarea = textEl.querySelector('textarea');
    textarea.focus();
    textarea.setSelectionRange(textarea.value.length, textarea.value.length);

    function save() {
        s.text = textarea.value.trim();
        conv.updated = Date.now();
        persistState();
        if (typeof updateStorageInfo === 'function') updateStorageInfo(); // 【Storage Fix】
        renderSummaryHistory();
        if (dom.summaryManagerModal && !dom.summaryManagerModal.classList.contains('hidden')) {
            renderSummaryManagerList();
        }
    }
    textarea.addEventListener('blur', save);
    textarea.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); save(); }
        if (e.key === 'Escape') { textarea.value = currentText; save(); }
    });
}

async function deleteSummary(id) {
    if (!await showGlassConfirm(t('summary_delete_confirm'), { title: '\u5220\u9664\u6458\u8981', danger: true, okText: '\u5220\u9664' })) return;
    var conv = getActiveConv();
    if (!conv) return;
    conv.summaries = conv.summaries.filter(function(s) { return s.id !== id; });
    conv.updated = Date.now();
    persistState();
    renderSummaryHistory();
    // 同时刷新管理器列表（如果打开着）
    if (dom.summaryManagerModal && !dom.summaryManagerModal.classList.contains('hidden')) {
        renderSummaryManagerList();
    }
}
/** Four-step first-run onboarding state. Completion is intentionally separate from app data. */
var ONBOARDING_COMPLETED_KEY = 'opentavern_onboarding_completed_v1';
var ONBOARDING_TOTAL_STEPS = 4;
var ONBOARDING_FEATURED_CARD_IDS = ['misono_mika', 'sakuraba_ema'];
var onboardingState = createOnboardingRuntimeState();

function createOnboardingRuntimeState() {
    return {
        step: 0,
        useRoleplayPrompt: true,
        selectedCards: {},
        skippedSteps: {},
        finishing: false
    };
}
function resetOnboardingRuntimeState() {
    onboardingState = createOnboardingRuntimeState();
    return onboardingState;
}

function shouldShowOnboarding() {
    try {
        return localStorage.getItem(ONBOARDING_COMPLETED_KEY) !== '1';
    } catch (_) {
        return true;
    }
}

function markOnboardingCompleted() {
    try { localStorage.setItem(ONBOARDING_COMPLETED_KEY, '1'); } catch (_) {}
}

function isOnboardingOpen() {
    var dialog = document.getElementById('onboardingDialog');
    return !!(dialog && (dialog.open || dialog.hasAttribute('open')));
}
/** Rendering and open/close behavior for the onboarding dialog. */
function getOnboardingElements() {
    return {
        dialog: document.getElementById('onboardingDialog'),
        stepMeta: document.getElementById('onboardingStepMeta'),
        dots: document.getElementById('onboardingProgressDots'),
        back: document.getElementById('onboardingBackBtn'),
        skipStep: document.getElementById('onboardingSkipStepBtn'),
        next: document.getElementById('onboardingNextBtn'),
        endpoint: document.getElementById('onboardingApiEndpoint'),
        apiKey: document.getElementById('onboardingApiKey'),
        saveApiKey: document.getElementById('onboardingSaveApiKey'),
        modelCatalog: document.getElementById('onboardingModelCatalog'),
        modelName: document.getElementById('onboardingModelName'),
        personaName: document.getElementById('onboardingPersonaName'),
        userName: document.getElementById('onboardingUserName'),
        userDescription: document.getElementById('onboardingUserDescription'),
        promptYes: document.getElementById('onboardingPromptYesBtn'),
        promptNo: document.getElementById('onboardingPromptNoBtn'),
        promptFeedback: document.getElementById('onboardingPromptFeedback'),
        cards: document.getElementById('onboardingFeaturedCards')
    };
}
function renderOnboardingModelOptions(models) {
    var elements = getOnboardingElements();
    if (!elements.modelCatalog) return;
    var selected = (elements.modelName && elements.modelName.value) || state.settings.model || '';
    elements.modelCatalog.innerHTML = '';
    var custom = document.createElement('option');
    custom.value = '';
    custom.textContent = t('settings_model_custom_option');
    elements.modelCatalog.appendChild(custom);
    (Array.isArray(models) ? models : []).forEach(function(modelId) {
        var option = document.createElement('option');
        option.value = modelId;
        option.textContent = modelId;
        elements.modelCatalog.appendChild(option);
    });
    elements.modelCatalog.value = (Array.isArray(models) && models.indexOf(selected) >= 0) ? selected : '';
}

function hydrateOnboardingForms() {
    var elements = getOnboardingElements();
    if (elements.endpoint) elements.endpoint.value = state.settings.apiEndpoint || '';
    if (elements.apiKey) elements.apiKey.value = state.settings.apiKey || '';
    if (elements.saveApiKey) elements.saveApiKey.checked = !!state.settings.saveApiKey;
    if (elements.modelName) elements.modelName.value = state.settings.model || 'gpt-4o';
    renderOnboardingModelOptions(state.settings.apiModelCatalog || []);

    ensureUserPersonaSettings(state.settings);
    var persona = getUserPersonaById(state.settings.activeUserPersonaId, state.settings) || state.settings.userPersonas[0];
    if (elements.personaName) elements.personaName.value = persona.name || getDefaultUserPersonaName(state.settings);
    if (elements.userName) elements.userName.value = persona.userName || 'User';
    if (elements.userDescription) elements.userDescription.value = persona.description || '';
}

function createOnboardingFeaturedCard(card) {
    var button = document.createElement('button');
    button.type = 'button';
    button.className = 'onboarding-card';
    button.dataset.cardId = card.id;
    button.setAttribute('aria-pressed', onboardingState.selectedCards[card.id] ? 'true' : 'false');
    button.classList.toggle('is-selected', !!onboardingState.selectedCards[card.id]);

    var preview = document.createElement('div');
    preview.className = 'onboarding-card-preview';
    var image = document.createElement('img');
    image.src = resolvePublicCardImageUrl(card);
    image.alt = card.name || '';
    image.loading = 'lazy';
    image.onerror = function() {
        preview.innerHTML = '';
        var fallback = document.createElement('span');
        fallback.className = 'onboarding-card-fallback';
        fallback.textContent = (card.name || '?').charAt(0);
        preview.appendChild(fallback);
    };
    preview.appendChild(image);

    var check = document.createElement('span');
    check.className = 'onboarding-card-check';
    check.textContent = '✓';
    preview.appendChild(check);

    var info = document.createElement('span');
    info.className = 'onboarding-card-info';
    var name = document.createElement('strong');
    name.textContent = card.name || card.id;
    var author = document.createElement('span');
    author.textContent = card.author || '';
    info.appendChild(name);
    info.appendChild(author);

    button.appendChild(preview);
    button.appendChild(info);
    return button;
}

function renderOnboardingFeaturedCards() {
    var host = document.getElementById('onboardingFeaturedCards');
    if (!host || typeof findPublicCardById !== 'function') return;
    host.innerHTML = '';
    ONBOARDING_FEATURED_CARD_IDS.forEach(function(id) {
        var card = findPublicCardById(id);
        if (card) host.appendChild(createOnboardingFeaturedCard(card));
    });
}

function renderOnboardingPromptChoice() {
    var elements = getOnboardingElements();
    var usePrompt = !!onboardingState.useRoleplayPrompt;
    [elements.promptYes, elements.promptNo].forEach(function(button, index) {
        if (!button) return;
        var selected = index === 0 ? usePrompt : !usePrompt;
        button.classList.toggle('is-selected', selected);
        button.setAttribute('aria-pressed', selected ? 'true' : 'false');
    });
    if (elements.promptFeedback) {
        elements.promptFeedback.textContent = t(usePrompt ? 'onboarding_prompt_selected' : 'onboarding_prompt_unchanged');
    }
}

function renderOnboardingStep() {
    var elements = getOnboardingElements();
    if (!elements.dialog) return;
    var step = Math.max(0, Math.min(ONBOARDING_TOTAL_STEPS - 1, onboardingState.step));
    onboardingState.step = step;
    elements.dialog.querySelectorAll('[data-onboarding-step]').forEach(function(panel) {
        panel.hidden = Number(panel.getAttribute('data-onboarding-step')) !== step;
    });
    if (elements.stepMeta) elements.stepMeta.textContent = (step + 1) + ' / ' + ONBOARDING_TOTAL_STEPS;
    if (elements.dots) {
        Array.from(elements.dots.children).forEach(function(dot, index) {
            dot.classList.toggle('is-active', index <= step);
            dot.classList.toggle('is-current', index === step);
        });
    }
    if (elements.back) elements.back.hidden = step === 0;
    if (elements.next) elements.next.textContent = t(step === ONBOARDING_TOTAL_STEPS - 1 ? 'onboarding_finish' : 'onboarding_next');
    renderOnboardingPromptChoice();
    var body = elements.dialog.querySelector('.onboarding-body');
    if (body) body.scrollTop = 0;
}

function showOnboarding() {
    var elements = getOnboardingElements();
    if (!elements.dialog) return false;
    resetOnboardingRuntimeState();
    hydrateOnboardingForms();
    renderOnboardingFeaturedCards();
    renderOnboardingStep();
    if (!elements.dialog.open) {
        if (typeof elements.dialog.showModal === 'function') elements.dialog.showModal();
        else elements.dialog.setAttribute('open', '');
    }
    document.body.classList.add('onboarding-open');
    return true;
}

function closeOnboarding() {
    var dialog = document.getElementById('onboardingDialog');
    if (!dialog) return;
    if (dialog.open && typeof dialog.close === 'function') dialog.close();
    else dialog.removeAttribute('open');
    document.body.classList.remove('onboarding-open');
}

function refreshOnboardingTranslations() {
    if (!isOnboardingOpen()) return;
    renderOnboardingModelOptions(state.settings.apiModelCatalog || []);
    renderOnboardingStep();
}

function scheduleOnboardingModal(delay) {
    if (!shouldShowOnboarding()) return;
    setTimeout(function() {
        if (!isAnyStartupModalOpen()) showOnboarding();
    }, typeof delay === 'number' ? delay : 220);
}
/** Persist each onboarding choice and import selected public cards on completion. */
function commitOnboardingApiSettings() {
    var elements = getOnboardingElements();
    state.settings.apiEndpoint = elements.endpoint ? elements.endpoint.value.trim() : state.settings.apiEndpoint;
    state.settings.apiKey = elements.apiKey ? elements.apiKey.value.trim() : state.settings.apiKey;
    state.settings.saveApiKey = !!(elements.saveApiKey && elements.saveApiKey.checked);
    state.settings.model = elements.modelName && elements.modelName.value.trim()
        ? elements.modelName.value.trim()
        : (state.settings.model || 'gpt-4o');
    persistState();
}
function commitOnboardingPersona() {
    var elements = getOnboardingElements();
    updateActiveUserPersona({
        name: elements.personaName ? elements.personaName.value.trim() : '',
        userName: elements.userName ? elements.userName.value.trim() : 'User',
        description: elements.userDescription ? elements.userDescription.value : ''
    });
    persistState();
}

function commitOnboardingPrompt() {
    if (!onboardingState.useRoleplayPrompt) return;
    state.settings.systemPrompt = BASE_SYSTEM_PROMPT;
    persistState();
}

function commitOnboardingStep(step) {
    if (step === 0) commitOnboardingApiSettings();
    else if (step === 1) commitOnboardingPersona();
    else if (step === 2) commitOnboardingPrompt();
}

function syncOnboardingApiProbeFields() {
    var elements = getOnboardingElements();
    if (dom.apiEndpoint && elements.endpoint) dom.apiEndpoint.value = elements.endpoint.value.trim();
    if (dom.apiKey && elements.apiKey) dom.apiKey.value = elements.apiKey.value.trim();
    if (dom.saveApiKey && elements.saveApiKey) dom.saveApiKey.checked = elements.saveApiKey.checked;
    if (dom.modelName && elements.modelName) dom.modelName.value = elements.modelName.value.trim() || 'gpt-4o';
}

async function testOnboardingApiConnection() {
    var button = document.getElementById('onboardingApiConnectBtn');
    var status = document.getElementById('onboardingApiStatus');
    if (button) button.disabled = true;
    if (status) {
        status.textContent = t('api_test_testing');
        status.dataset.kind = 'busy';
    }
    syncOnboardingApiProbeFields();
    try {
        var result = await window.testMainApiConnection();
        var models = result && Array.isArray(result.models) ? result.models : [];
        renderOnboardingModelOptions(models);
        if (status) {
            status.textContent = result && result.ok
                ? t('onboarding_api_connected').replace('{n}', String(models.length))
                : t('onboarding_api_failed');
            status.dataset.kind = result && result.ok ? 'success' : 'error';
        }
        return !!(result && result.ok);
    } catch (err) {
        if (status) {
            status.textContent = t('onboarding_api_failed') + ' ' + ((err && err.message) || String(err));
            status.dataset.kind = 'error';
        }
        return false;
    } finally {
        if (button) button.disabled = false;
    }
}

function toggleOnboardingFeaturedCard(cardId) {
    if (ONBOARDING_FEATURED_CARD_IDS.indexOf(cardId) < 0) return;
    onboardingState.selectedCards[cardId] = !onboardingState.selectedCards[cardId];
    var card = document.querySelector('#onboardingFeaturedCards [data-card-id="' + cardId + '"]');
    if (card) {
        card.classList.toggle('is-selected', !!onboardingState.selectedCards[cardId]);
        card.setAttribute('aria-pressed', onboardingState.selectedCards[cardId] ? 'true' : 'false');
    }
}

async function importOnboardingFeaturedCards() {
    var selected = ONBOARDING_FEATURED_CARD_IDS.filter(function(id) {
        return !!onboardingState.selectedCards[id];
    });
    var status = document.getElementById('onboardingCardsStatus');
    if (!selected.length) return { imported: 0, failed: 0 };

    var imported = 0;
    var failed = 0;
    var previousSuppress = window.__suppressPublicCardImportToast;
    window.__suppressPublicCardImportToast = true;
    try {
        for (var i = 0; i < selected.length; i++) {
            var card = findPublicCardById(selected[i]);
            if (!card) {
                failed += 1;
                continue;
            }
            if (status) status.textContent = t('onboarding_cards_importing').replace('{name}', card.name || card.id);
            var importedCharacter = await importPublicCard(card);
            if (importedCharacter) imported += 1;
            else failed += 1;
        }
    } finally {
        if (typeof previousSuppress === 'undefined') delete window.__suppressPublicCardImportToast;
        else window.__suppressPublicCardImportToast = previousSuppress;
    }
    return { imported: imported, failed: failed };
}

async function finishOnboarding(skipCurrentStep) {
    if (onboardingState.finishing) return;
    onboardingState.finishing = true;
    var elements = getOnboardingElements();
    if (elements.next) elements.next.disabled = true;
    if (!skipCurrentStep) commitOnboardingStep(onboardingState.step);

    var result = { imported: 0, failed: 0 };
    if (!skipCurrentStep && onboardingState.step === ONBOARDING_TOTAL_STEPS - 1) {
        result = await importOnboardingFeaturedCards();
    }
    markOnboardingCompleted();
    await persistState(true);
    closeOnboarding();
    onboardingState.finishing = false;
    if (elements.next) elements.next.disabled = false;
    if (result.imported && typeof showGlassAlert === 'function') {
        showGlassAlert(t('onboarding_cards_imported').replace('{n}', String(result.imported)), {
            title: t('onboarding_complete_title')
        });
    }
}
/** Event binding for navigation, API probing, prompt choice and card selection. */
function moveOnboardingForward(skipStep) {
    if (onboardingState.step >= ONBOARDING_TOTAL_STEPS - 1) {
        finishOnboarding(!!skipStep);
        return;
    }
    if (skipStep) onboardingState.skippedSteps[onboardingState.step] = true;
    else commitOnboardingStep(onboardingState.step);
    onboardingState.step += 1;
    renderOnboardingStep();
}
function setOnboardingPromptChoice(usePrompt) {
    onboardingState.useRoleplayPrompt = !!usePrompt;
    renderOnboardingPromptChoice();
}

function bindOnboardingEvents() {
    var elements = getOnboardingElements();
    if (!elements.dialog || elements.dialog._onboardingEventsBound) return;
    elements.dialog._onboardingEventsBound = true;

    var skipAll = document.getElementById('onboardingSkipAllBtn');
    var connect = document.getElementById('onboardingApiConnectBtn');
    var replay = document.getElementById('onboardingReplayBtn');

    if (skipAll) skipAll.addEventListener('click', function() { finishOnboarding(true); });
    if (elements.back) elements.back.addEventListener('click', function() {
        onboardingState.step = Math.max(0, onboardingState.step - 1);
        renderOnboardingStep();
    });
    if (elements.skipStep) elements.skipStep.addEventListener('click', function() { moveOnboardingForward(true); });
    if (elements.next) elements.next.addEventListener('click', function() { moveOnboardingForward(false); });
    if (connect) connect.addEventListener('click', testOnboardingApiConnection);
    if (elements.modelCatalog) elements.modelCatalog.addEventListener('change', function() {
        if (this.value && elements.modelName) elements.modelName.value = this.value;
    });
    if (elements.promptYes) elements.promptYes.addEventListener('click', function() { setOnboardingPromptChoice(true); });
    if (elements.promptNo) elements.promptNo.addEventListener('click', function() { setOnboardingPromptChoice(false); });
    if (elements.cards) elements.cards.addEventListener('click', function(event) {
        var card = event.target.closest('[data-card-id]');
        if (card) toggleOnboardingFeaturedCard(card.dataset.cardId);
    });
    elements.dialog.addEventListener('cancel', function(event) {
        event.preventDefault();
        finishOnboarding(true);
    });
    elements.dialog.addEventListener('click', function(event) {
        if (event.target === elements.dialog) finishOnboarding(true);
    });

    if (replay) replay.addEventListener('click', function() {
        if (!dom.settingsModal.classList.contains('hidden')) closeSettings();
        setTimeout(showOnboarding, 120);
    });
}
