var messageJumpSequence = 0;
async function jumpToConversationMessage(conversationId, messageId) {
    var sequence = ++messageJumpSequence;
    if (state.activeConvId !== conversationId) await loadConversation(conversationId);
    var conv = state.conversations[conversationId];
    if (sequence !== messageJumpSequence || !conv || getActiveConv() !== conv) return false;
    var visible = getRenderableChatMessages(conv);
    var index = visible.findIndex(function(message) { return message.id === messageId; });
    if (index < 0) return false;
    conv._historyWindow = Math.max(conv._historyWindow || 150, visible.length - index);
    conv._lastRenderedVisibleCount = 0;
    renderMessagesOnly();
    await new Promise(function(resolve) { requestAnimationFrame(resolve); });
    if (sequence !== messageJumpSequence || getActiveConv() !== conv) return false;
    var element = Array.from(dom.messagesContainer.querySelectorAll('[data-message-id]')).find(function(node) { return node.dataset.messageId === messageId; });
    if (!element) return false;
    element.scrollIntoView({ block: 'center', behavior: 'instant' });
    element.classList.add('message-jump-target');
    setTimeout(function() { element.classList.remove('message-jump-target'); }, 1800);
    return true;
}

function openMessageFinder(favoritesOnly) {
    var dialog = openFeatureDialog('messageFinderDialog', favoritesOnly ? '会话收藏' : '消息搜索',
        featureField('搜索原始正文', 'messageFindQuery', '') +
        featureSelect('范围', 'messageFindScope', 'current', [['current', '当前会话'], ['all', '全部会话']]) +
        '<p class="feature-hint" data-find-count></p><div data-find-results></div>', null);
    var query = dialog.querySelector('#messageFindQuery'), scope = dialog.querySelector('#messageFindScope');
    var timer, shown = 100, results = [];
    function render() {
        dialog.querySelector('[data-find-count]').textContent = results.length + ' 条结果' + (results.length > shown ? '，显示前 ' + shown + ' 条' : '');
        dialog.querySelector('[data-find-results]').innerHTML = results.slice(0, shown).map(function(result, index) {
            return '<button type="button" class="feature-search-result" data-find-result="' + index + '"><strong>' + escapeHtml(result.title || '未命名会话') + ' · ' + escapeHtml(result.sender) + '</strong><span>' + escapeHtml(result.snippet || '附件消息') + '</span></button>';
        }).join('') + (results.length > shown ? '<button type="button" data-find-more>显示更多</button>' : '');
    }
    function search() { shown = 100; results = findConversationMessages(query.value, scope.value, favoritesOnly); render(); }
    query.oninput = function() { clearTimeout(timer); timer = setTimeout(search, 150); };
    scope.onchange = search;
    dialog.addEventListener('close', function() { clearTimeout(timer); });
    dialog.addEventListener('click', async function(event) {
        if (event.target.closest('[data-find-more]')) { shown += 100; render(); return; }
        var button = event.target.closest('[data-find-result]');
        if (!button) return;
        var result = results[Number(button.dataset.findResult)];
        dialog.close();
        if (!await jumpToConversationMessage(result.conversationId, result.messageId)) alert('原消息已删除或会话切换已取消');
    });
    search();
}

function openConversationMembers() {
    var conv = getActiveConv();
    if (!conv || state.isGenerating) { alert('请先停止生成'); return; }
    var original = JSON.stringify([conv.group, conv.character]);
    var members = JSON.parse(JSON.stringify(conv.group && conv.group.members || (conv.character ? [{ character: conv.character, muted: false, order: 0 }] : [])));
    var choices = Object.keys(state.characters || {}).map(function(key) { return [key, state.characters[key].name]; });
    var dialog = openFeatureDialog('conversationMembersDialog', '会话成员',
        '<p class="feature-hint">只调整后续发言，保留历史消息、摘要和发言身份。</p><div data-member-list></div>' +
        featureSelect('从角色库添加', 'memberCharacter', '', [['', '选择角色']].concat(choices)) + '<button type="button" data-member-add>添加成员</button>', async function() {
            if (JSON.stringify([conv.group, conv.character]) !== original) throw new Error('成员已变化，请重新打开');
            await saveConversationMembers(conv, members);
        });
    function render() {
        dialog.querySelector('[data-member-list]').innerHTML = members.map(function(member, index) {
            return '<div class="feature-row"><span><strong>' + escapeHtml(member.character.name) + '</strong><label class="feature-check"><input type="checkbox" data-member-mute="' + index + '"' + (member.muted ? ' checked' : '') + '>静音</label></span>' +
                '<button type="button" data-member-move="' + index + '" data-direction="-1"' + (!index ? ' disabled' : '') + '>上移</button><button type="button" data-member-move="' + index + '" data-direction="1"' + (index === members.length - 1 ? ' disabled' : '') + '>下移</button><button type="button" data-member-remove="' + index + '">移除</button></div>';
        }).join('');
    }
    dialog.addEventListener('change', function(event) { if (event.target.dataset.memberMute != null) members[Number(event.target.dataset.memberMute)].muted = event.target.checked; });
    dialog.addEventListener('click', function(event) {
        var button = event.target.closest('button'); if (!button) return;
        if (button.hasAttribute('data-member-add')) {
            var character = state.characters[dialog.querySelector('#memberCharacter').value];
            if (character && !members.some(function(member) { return member.character.name.toLowerCase() === character.name.toLowerCase(); })) members.push({ character: JSON.parse(JSON.stringify(character)), muted: false, order: members.length });
        }
        if (button.dataset.memberRemove != null) members.splice(Number(button.dataset.memberRemove), 1);
        if (button.dataset.memberMove != null) {
            var from = Number(button.dataset.memberMove), to = from + Number(button.dataset.direction);
            if (to >= 0 && to < members.length) { var moved = members.splice(from, 1)[0]; members.splice(to, 0, moved); }
        }
        render();
    });
    render();
}

function bindChatOperationsEntries() {
    var parent = document.getElementById('conversationPromptControls').parentElement;
    parent.classList.add('feature-chat-tools');
    [['messageSearchEntry', '搜索', function() { openMessageFinder(false); }], ['messageFavoritesEntry', '收藏', function() { openMessageFinder(true); }], ['conversationMembersEntry', '成员', openConversationMembers]].forEach(function(entry) {
        var button = document.createElement('button'); button.type = 'button'; button.id = entry[0]; button.className = 'feature-entry feature-entry-compact'; button.textContent = entry[1]; button.onclick = entry[2]; parent.appendChild(button);
    });
}
var userDraftRequest = null;
var userDraftEditSequence = 0;

function updateUserDraftButton() {
    var button = document.getElementById('userDraftBtn');
    if (!button) return;
    button.textContent = userDraftRequest ? '取消' : '代写';
    button.title = userDraftRequest ? '取消生成，保留输入' : '按用户设定生成草稿，确认后自行发送';
    button.setAttribute('aria-label', button.title);
    button.setAttribute('aria-pressed', userDraftRequest ? 'true' : 'false');
    button.disabled = !userDraftRequest && (!getActiveConv() || state.isGenerating || !state.settings.apiEndpoint || !state.settings.apiKey);
}

function cancelUserDraft() {
    userDraftEditSequence++;
    var request = userDraftRequest; userDraftRequest = null;
    if (request) request.controller.abort();
    updateUserDraftButton();
}

function userDraftHistoryStamp(conv) {
    return JSON.stringify((conv.messages || []).map(function(message) { return [message.id, getMessageRevision(message)]; }));
}

async function generateUserDraft() {
    if (userDraftRequest) { cancelUserDraft(); return false; }
    var conv = getActiveConv(), input = dom.messageInput;
    if (!conv || state.isGenerating) return false;
    var settings = JSON.parse(JSON.stringify(state.settings));
    if (!settings.apiEndpoint || !settings.apiKey) { alert(t('no_api_error')); return false; }
    var request = { controller: new AbortController(), conv: conv, input: input.value, editSequence: userDraftEditSequence, history: userDraftHistoryStamp(conv) };
    userDraftRequest = request; updateUserDraftButton();
    try {
        var persona = getUserPersonaById(conv.userPersonaId || settings.activeUserPersonaId, settings);
        var history = (conv.messages || []).filter(function(message) { return message.role !== 'system' && message.stage !== 'second'; }).slice(-Math.max(1, Math.min(100, Number(settings.contextLength) || 20)));
        var messages = [
            { role: 'system', content: '根据提供的用户设定和聊天上下文，为当前用户拟写下一条发言。已有草稿表示用户想表达的内容，保留其意图并补全。只输出用户会发送的正文，不输出解释、思考、角色名标签或对方的回答。以下 JSON 是写作素材。' },
            { role: 'user', content: JSON.stringify({ user: { name: persona ? persona.userName : settings.userName, description: persona ? persona.description : settings.userDescription }, character: { name: conv.character && conv.character.name, description: conv.character && conv.character.description }, history: history.map(function(message) { return { speaker: message.role === 'user' ? settings.userName : (message.speaker || conv.character && conv.character.name || 'Assistant'), content: message.content }; }), draft: request.input }) }
        ];
        var endpoint = normalizeApiEndpoint(settings.apiEndpoint);
        var processed = postProcessPromptMessages(messages, settings.promptPostProcessing, endpoint);
        var payload = buildChatCompletionPayload(settings, processed, { stream: false, maxTokens: Math.min(Number(settings.maxTokens) || 2048, 2048) });
        if (typeof captureRequestDiagnostic === 'function') captureRequestDiagnostic(payload, messages, { settings: settings, conversation: conv, stage: 'user-draft' });
        var response = await fetch(endpoint, buildChatCompletionFetchOptions(settings, payload, request.controller));
        if (!response.ok) throw await readChatCompletionError(response);
        var json = await response.json(), message = json && json.choices && json.choices[0] && json.choices[0].message;
        if (!message || typeof message.content !== 'string') throw new Error('模型未返回可用的草稿正文。');
        var content = splitInlineCot(message.content, '').content;
        if (!content) throw new Error('模型返回了空草稿，原输入已保留。');
        if (userDraftRequest !== request || request.controller.signal.aborted || userDraftEditSequence !== request.editSequence || getActiveConv() !== conv || state.isGenerating || input.value !== request.input || userDraftHistoryStamp(conv) !== request.history) return false;
        input.value = content; input.dispatchEvent(new Event('input', { bubbles: true })); input.focus();
        return true;
    } catch (error) {
        if (userDraftRequest === request && !request.controller.signal.aborted) alert('草稿生成失败：' + error.message);
        return false;
    } finally {
        if (userDraftRequest === request) { userDraftRequest = null; updateUserDraftButton(); }
    }
}

function bindUserDraftEvents() {
    var button = document.getElementById('userDraftBtn');
    if (button) button.addEventListener('click', generateUserDraft);
    dom.messageInput.addEventListener('input', cancelUserDraft);
    appStore.subscribe(function() {
        if (userDraftRequest && (getActiveConv() !== userDraftRequest.conv || state.isGenerating)) cancelUserDraft();
        updateUserDraftButton();
    });
    updateUserDraftButton();
}
// Explicit review and page-local consent; no field is written to settings.
var cardRuntimeDialog = null;

function openCardRuntimeDialog(id, title, body, onSave, options) {
    if (cardRuntimeDialog && cardRuntimeDialog.isConnected) cardRuntimeDialog.close();
    options = options || {};
    var onClose = options.onClose, dialog;
    options.onClose = function() { if (cardRuntimeDialog === dialog) cardRuntimeDialog = null; if (onClose) onClose(); };
    dialog = openFeatureDialog(id, title, body, onSave, options); cardRuntimeDialog = dialog;
    return dialog;
}

function cardRuntimeSelection(dialog) {
    var level = dialog.querySelector('[data-runtime-level]').value, permissions = {}, network = {};
    if (!['L0', 'L1', 'L2', 'L3'].includes(level)) throw cardRuntimeError('INVALID_LEVEL', '请选择运行级别。');
    dialog.querySelectorAll('[data-runtime-permission]').forEach(function(input) { permissions[input.getAttribute('data-runtime-permission')] = input.checked; });
    if (level === 'L3') {
        var address;
        try { address = new URL(dialog.querySelector('[data-runtime-broker]').value.trim()); } catch (_) { throw cardRuntimeError('INVALID_NETWORK', '请填写完整的 HTTP 或 HTTPS 联网服务地址。'); }
        if (!['http:', 'https:'].includes(address.protocol) || address.username || address.password || address.origin === location.origin) throw cardRuntimeError('INVALID_NETWORK', '联网服务须使用与应用不同源且不含凭据的 HTTP 或 HTTPS 地址。');
        var origins = dialog.querySelector('[data-runtime-origins]').value.split(/[\s,]+/).filter(Boolean).map(function(value) {
            var origin;
            try { origin = new URL(value); } catch (_) { throw cardRuntimeError('INVALID_NETWORK', '允许访问的来源格式不正确。'); }
            if (!['http:', 'https:'].includes(origin.protocol) || origin.username || origin.password || origin.pathname !== '/' || origin.search || origin.hash) throw cardRuntimeError('INVALID_NETWORK', '每个允许来源只填写协议、主机和端口。');
            return origin.origin;
        });
        if (!origins.length || origins.length > 16) throw cardRuntimeError('INVALID_NETWORK', '请填写 1–16 个允许访问的来源。');
        var methods = Array.from(dialog.querySelectorAll('[data-runtime-method]:checked'), function(input) { return input.value; });
        if (!methods.length) throw cardRuntimeError('INVALID_NETWORK', '至少选择一种请求方法。');
        if (!permissions['network.fetch']) throw cardRuntimeError('PERMISSION_DENIED', 'L3 需要明确勾选联网权限。');
        network = { brokerUrl: address.href, origins: Array.from(new Set(origins)), methods: methods };
    } else permissions['network.fetch'] = false;
    return { level: level, permissions: permissions, network: network };
}

function chooseCardRuntimePermissions(entry, controller) {
    return new Promise(function(resolve) {
        var accepted = false;
        var body = '<p class="feature-hint">卡片脚本将在隔离窗口中运行。许可仅在本页有效；修改内容、切换目标或撤销后需重新确认。</p>' +
            '<label class="feature-field"><span>运行级别</span><select data-runtime-level><option value="L0">L0 · 仅卡片内联脚本</option><option value="L1">L1 · 固定基础库</option><option value="L2">L2 · 下载并审核完整依赖</option><option value="L3">L3 · 受限联网服务</option></select></label>' +
            '<p class="feature-hint" data-runtime-level-hint>L0 不下载外部脚本，不开放联网接口。</p><fieldset class="card-runtime-permissions"><legend>允许的操作</legend>' +
            Object.keys(cardRuntimeCapabilities).map(function(key) { return '<label><input type="checkbox" data-runtime-permission="' + key + '"><span>' + escapeHtml(cardRuntimeCapabilities[key]) + '</span></label>'; }).join('') + '</fieldset>' +
            '<fieldset class="card-runtime-network" data-runtime-network hidden><legend>联网范围</legend>' +
            '<label class="feature-field"><span>不同源联网服务地址</span><input type="url" data-runtime-broker placeholder="http://localhost:8766/index.html"></label>' +
            '<label class="feature-field"><span>允许访问的来源，每行一个</span><textarea rows="3" data-runtime-origins placeholder="https://example.com"></textarea></label>' +
            '<div class="feature-toolbar">' + ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'].map(function(method) { return '<label><input type="checkbox" data-runtime-method value="' + method + '"' + (method === 'GET' ? ' checked' : '') + '> ' + method + '</label>'; }).join('') + '</div></fieldset>';
        var dialog = openCardRuntimeDialog('cardRuntimePermissionDialog', '运行卡片', body, function(current) {
            if (controller.signal.aborted || !cardRuntimeEntryIsCurrent(entry)) throw cardRuntimeError('STALE_TARGET', '会话或消息已变化，请重新打开。');
            var selection = cardRuntimeSelection(current); accepted = true; resolve(selection);
        }, { saveLabel: '准备并审核', onClose: function() { if (!accepted) { controller.abort(); resolve(null); } } });
        controller.signal.addEventListener('abort', function() { if (dialog.isConnected && dialog.open) dialog.close(); }, { once: true });
        dialog.querySelector('[data-runtime-level]').addEventListener('change', function(event) {
            var level = event.target.value;
            dialog.querySelector('[data-runtime-network]').hidden = level !== 'L3';
            dialog.querySelector('[data-runtime-level-hint]').textContent = { L0: 'L0 不下载外部脚本，不开放联网接口。', L1: 'L1 使用已固定版本的基础库，不开放联网接口。', L2: '准备将下载依赖供你审核；确认运行前不会执行。', L3: '准备将固定依赖；联网接口通过所选服务访问允许来源。' }[level];
        });
    });
}

function cardRuntimeReviewHtml(grant) {
    var allowed = Object.keys(cardRuntimeCapabilities).filter(function(key) { return grant.permissions[key]; });
    var dependencies = grant.plan.scripts.concat(grant.plan.modules || []);
    return '<div class="card-runtime-review"><p>运行级别：' + escapeHtml(grant.level) + '</p><p class="feature-hint">许可绑定下列内容和操作；停止不会回退已保存的变量。</p>' +
        '<p class="feature-hint">窗口自行跳转可能发出请求，脚本也可持续占用资源。请仅运行可信卡片。</p>' +
        '<p>允许：' + escapeHtml(allowed.length ? allowed.map(function(key) { return cardRuntimeCapabilities[key]; }).join('；') : '仅读取承载此卡片的消息身份') + '</p>' +
        '<p>内容 SHA-256：<code>' + escapeHtml(grant.sourceDigest) + '</code></p><p>完整许可 SHA-256：<code>' + escapeHtml(grant.digest) + '</code></p>' +
        (grant.level === 'L3' ? '<p>联网服务：' + escapeHtml(grant.network.brokerUrl) + '</p><p>来源：' + escapeHtml(grant.network.origins.join('；')) + '</p><p>方法：' + escapeHtml(grant.network.methods.join('、')) + '</p>' : '') +
        '<details><summary>固定依赖（' + dependencies.length + '）</summary>' + dependencies.map(function(script) { return '<div class="card-runtime-dependency"><p>' + escapeHtml(script.name || script.url || script.id || '内联模块') + ' · ' + cardRuntimeBytes(script.source) + ' 字节</p><code>' + escapeHtml(script.sha256) + '</code><details><summary>查看源码</summary><pre><code>' + escapeHtml(script.source) + '</code></pre></details></div>'; }).join('') + '</details>' +
        '<details><summary>查看卡片原文</summary><pre><code>' + escapeHtml(grant.source) + '</code></pre></details></div>';
}

async function reviewCardRuntimeGrant(entry, selection, controller) {
    var grant = null, finish;
    var completed = new Promise(function(resolve) { finish = resolve; });
    var dialog = openCardRuntimeDialog('cardRuntimeReviewDialog', '审核卡片内容', '<p class="feature-hint">正在准备所选内容，完成后可查看依赖摘要和源码。</p>', function() {
        if (!grant || controller.signal.aborted) return false;
        activateCardRuntimeGrant(entry, grant);
        mountCardRuntimeFrames(dom.messagesContainer || document);
        finish(true);
    }, { saveLabel: '确认运行', onClose: function() { controller.abort(); finish(false); } });
    controller.signal.addEventListener('abort', function() { if (dialog.isConnected && dialog.open) dialog.close(); }, { once: true });
    dialog.querySelector('button[type="submit"]').disabled = true;
    try {
        grant = await prepareCardRuntimeGrant(entry, selection, controller.signal);
        if (controller.signal.aborted || !dialog.isConnected) return false;
        dialog.querySelector('.feature-dialog-body').innerHTML = cardRuntimeReviewHtml(grant);
        dialog.querySelector('button[type="submit"]').disabled = false;
    } catch (error) {
        if (!controller.signal.aborted && dialog.isConnected) {
            dialog.querySelector('.feature-error').textContent = error.message || String(error);
            dialog.querySelector('.feature-dialog-body').textContent = '准备失败，卡片保持静态显示。关闭后可重新选择运行级别。';
        }
    }
    return completed;
}

async function requestCardRuntimeRun(entry) {
    if (entry.pending) return;
    var controller = new AbortController(); entry.pending = controller;
    try {
        var selection = await chooseCardRuntimePermissions(entry, controller);
        if (selection && !controller.signal.aborted) await reviewCardRuntimeGrant(entry, selection, controller);
    } finally { if (entry.pending === controller) entry.pending = null; }
}

function revokeCardRuntimeEntry(entry) {
    cardRuntimeGrants.forEach(function(grant, key) { if (grant.cardKey === entry.cardKey && grant.source === entry.source) cardRuntimeGrants.delete(key); });
    Array.from(cardRuntimeInstances.values()).forEach(function(instance) { if (instance.entry.cardKey === entry.cardKey && instance.entry.source === entry.source) stopCardRuntimeInstance(instance, '已停止并撤销；原文及已保存的变量保留', false); });
    if (entry.pending) entry.pending.abort();
}

function handleCardRuntimeAction(action, element) {
    if (!['card-runtime-run', 'card-runtime-revoke', 'card-runtime-details'].includes(action)) return false;
    var owner = element && element.closest('[data-card-runtime-token]'), entry = owner && cardRuntimeEntries.get(owner.getAttribute('data-card-runtime-token'));
    if (!entry) return true;
    if (action === 'card-runtime-revoke') { revokeCardRuntimeEntry(entry); return true; }
    if (action === 'card-runtime-details') {
        var grant = findCardRuntimeGrant(entry);
        openCardRuntimeDialog('cardRuntimeDetailsDialog', '卡片运行详情', grant ? cardRuntimeReviewHtml(grant) : '<p class="feature-hint">尚未授权运行，当前仅显示静态内容。</p><details><summary>查看原文</summary><pre><code>' + escapeHtml(entry.source) + '</code></pre></details>', null);
        return true;
    }
    requestCardRuntimeRun(entry).catch(function(error) { openCardRuntimeDialog('cardRuntimeErrorDialog', '卡片未运行', '<p class="feature-hint">' + escapeHtml(error.message || String(error)) + '</p>', null); });
    return true;
}
