    bindSettingsSlider(dom.streamTextAnimStagger, dom.streamTextAnimStaggerVal);
    bindSettingsSlider(dom.streamIdleTimeoutSec, dom.streamIdleTimeoutVal, formatStreamIdleTimeoutLabel);

